scenarios.example_code:
import { declareIndex } from '@projexlight/sdk-search';
await declareIndex({
  tenant_id, name: 'contacts',
  entity_kind: 'crm.contact',
  field_map: { full_name: 'text-fuzzy', company: 'keyword', email: 'keyword', custom: 'object' },
  partition_by: 'territory_id',
});

import { query } from '@projexlight/sdk-search';
const hits = await query({
  tenant_id, persona_id, index: 'contacts',
  q: 'company:acme', filters: { stage_in: ['open','negotiation'] },
  page_size: 20,
});

import { saveQuery } from '@projexlight/sdk-search';
await saveQuery({
  tenant_id, name: 'enterprise-stalled-30d',
  q: 'stage:negotiation', filters: { tier: 'enterprise', last_activity_lt: 'now-30d' },
  refresh_cadence_min: 1440, alert_on_diff: true,
});

import { reindexPartition } from '@projexlight/sdk-search';
await reindexPartition({
  index: 'contacts', partition: 'territory:us-east',
});

import { query } from '@projexlight/sdk-search';
const hits = await query({
  tenant_id, persona_id, index: 'contacts',
  q: 'who at acme owns billing decisions', mode: 'hybrid',
});
